mapper.select:
select mn.*
from Sec_Publicity_Cpy mn
where mn.Pr_Id = #{prId}

select
mn.* from Sec_Project mn
left join Sec_Info sec on sec.Sec_Id = mn.Sec_Id left join Sec_Publicity_Results sd on sd.Sec_Id = sec.Sec_Id where sd.Pr_Id = #{prId}

select sec.Sec_Name as secName, sec.Sec_Code as secCode, c1.C_Name_History as prTendereeNameHistory, c2.C_Name_History as prBidWinnerNameHistory, c1.C_Name as prTendereeName, c2.C_Name as prBidWinnerName, c1.C_Abbreviation as prTendereeAbbName, c2.C_Abbreviation as prBidWinAbbName, mn.* from Sec_Publicity_Results mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Pr_Tenderee=c1.C_Id left join SYS_Company c2 on mn.Pr_Bid_Winner=c2.C_Id where 1=1
order by mn.${params.sortFiled} ${params.sortType}
limit #{params.start},#{params.size}

select sec.Sec_Name as secName, sec.Sec_Code as secCode, c1.C_Name_History as prTendereeNameHistory, c2.C_Name_History as prBidWinnerNameHistory, c1.C_Name as prTendereeName, c2.C_Name as prBidWinnerName, c1.C_Abbreviation as prTendereeAbbName, c2.C_Abbreviation as prBidWinAbbName,
mn.* from Sec_Publicity_Results mn left join Sec_Info sec on sec.Sec_Id=mn.Sec_Id left join SYS_Company c1 on mn.Pr_Tenderee=c1.C_Id left join SYS_Company c2 on mn.Pr_Bid_Winner=c2.C_Id where 1=1
order by pId asc limit #{params.start},#{params.size}
